CREATE TABLE api_sessions (session_id uuid PRIMARY KEY, user_id text NOT NULL, account_id uuid NOT NULL, token_hash char(64) NOT NULL UNIQUE, csrf_hash char(64) NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, CHECK (expires_at > created_at));
CREATE TABLE api_user_action_audits (audit_id uuid PRIMARY KEY, user_id text NOT NULL, account_id uuid NOT NULL, action text NOT NULL, object_id uuid, before_version integer, after_version integer, result text NOT NULL, occurred_at timestamptz NOT NULL, correlation_id text NOT NULL, details jsonb NOT NULL);
CREATE TABLE api_ui_preferences (preference_id uuid PRIMARY KEY, user_id text NOT NULL UNIQUE, theme text NOT NULL, timezone_name text NOT NULL, page_size integer NOT NULL CHECK (page_size BETWEEN 10 AND 200), updated_at timestamptz NOT NULL, version integer NOT NULL CHECK (version >= 0));
CREATE TABLE api_import_sessions (import_session_id uuid PRIMARY KEY, account_id uuid NOT NULL, user_id text NOT NULL, file_hash varchar(128) NOT NULL, format_version varchar(64) NOT NULL, columns jsonb NOT NULL, row_count integer NOT NULL CHECK (row_count >= 0), preview_passed boolean NOT NULL, summary jsonb NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('PREVIEWED','COMMITTED','EXPIRED','FAILED')), committed_result_id uuid, version integer NOT NULL CHECK (version >= 0), UNIQUE(account_id,file_hash,format_version), CHECK (expires_at > created_at));
CREATE TABLE api_idempotent_commands (command_id uuid PRIMARY KEY, user_id text NOT NULL, action text NOT NULL, idempotency_key varchar(128) NOT NULL, payload_hash char(64) NOT NULL, status_code integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL, UNIQUE(user_id,action,idempotency_key));
CREATE TABLE api_ui_events (event_id uuid PRIMARY KEY, event_type text NOT NULL, account_id uuid NOT NULL, occurred_at timestamptz NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL);
